import re,html.parser
src=open('chinese-typography-onepager.html',encoding='utf-8').read()
VOID={'br','hr','meta','link','img','input','source'}
class P(html.parser.HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True); self.stack=[]; self.err=[]
    def handle_starttag(self,tag,attrs):
        if tag not in VOID: self.stack.append(tag)
    def handle_endtag(self,tag):
        if tag in VOID: return
        if not self.stack or self.stack[-1]!=tag:
            self.err.append(f'mismatch </{tag}> at {self.getpos()}, open={self.stack[-3:]}')
            if tag in self.stack:
                while self.stack and self.stack.pop()!=tag: pass
        else: self.stack.pop()
p=P(); p.feed(src)
print('unclosed:',p.stack)
print('errors:',p.err or 'none')
print('od-ids:',len(re.findall(r'data-od-id=',src)))
